with flagged as (select *, case when paid_at - lag(paid_at) over (partition by status order by paid_at, id) > interval '30' day then 1 else 0 end as is_new_burst from payments), sessionized as (select *, sum(is_new_burst) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as session_no from flagged) select case when session_no >= 7 then 'HIGH' else 'LOW' end as session_no_tier, sort_array(collect_set(method)) as method_list, round(avg(session_no), 2) as avg_session_no, count(*) as cnt, count_if(status = 'REFUNDED') as refunded_events, round(avg(is_new_burst), 2) as avg_is_new_burst from sessionized group by case when session_no >= 7 then 'HIGH' else 'LOW' end having avg_is_new_burst > 0 order by avg_is_new_burst nulls first;
